let chatId;
let text;
let data;
let message_id;
let voice_id;
let audio_file_id;
let reply_to_message_id;
let reply_to_message_text;
let message_time;
let status = 'null';
let isReply = false; 
let isVoice = false;
let is_audio_doc = false;

const json = $input.first().json;

message_id = json.message?.message_id || json.callback_query?.message?.message_id;
text = json.message?.text || json.callback_query?.message?.text;
message_time = json.message?.date || json.callback_query?.message?.date;

if (json.message) {

  chatId = json.message.chat.id;

  // 1️⃣ VOICE MESSAGE
  if (json.message.voice) {
    isVoice = true;
    voice_id = json.message.voice.file_id;
  }

  // 2️⃣ AUDIO DOCUMENT (mp3 etc)
  if (json.message.audio) {
    is_audio_doc = true;
    audio_file_id = json.message.audio.file_id;
  }

  // 3️⃣ REPLY CHECK
  if (json.message.reply_to_message) {
    isReply = true;
    reply_to_message_id = json.message.reply_to_message.message_id;
    reply_to_message_text =
      json.message.reply_to_message.text ||
      json.message.reply_to_message.caption;
  }

} else if (json.callback_query) {

  chatId = json.callback_query.message.chat.id;
  data = json.callback_query.data;

}

return [{
  json: {
    chatId,
    text,
    message_id,
    data,
    voice_id,
    audio_file_id,
    reply_to_message_text,
    reply_to_message_id,
    message_time,
    status,
    isVoice,
    is_audio_doc,
    isReply
  }
}];

