// Helper function to safely fetch data without crashing n8n if a node is missing
function getSafeLink(nodeName, property) {
  try {
    return $(nodeName).first().json[property];
  } catch (error) {
    return null; // Returns null if the node doesn't exist or didn't run
  }
}

// 1. Fetching base details safely
